// Circuit Tracks firmware .syx <-> raw image, and LOOP06 built from the official file in the
// browser. A port of circuit/fw.py (format: docs/circuit-protocol.md); the patch itself is
// src/firmware-patch.js, generated by circuit/make_patch.py.

import PATCH from './firmware-patch.js';

const HDR = [0xF0, 0x00, 0x20, 0x29, 0x00];
const PROTO = 0x572, PRODUCT = 0x64;

export async function sha256(buf) {
  return [...new Uint8Array(await crypto.subtle.digest('SHA-256', buf))].map(b => b.toString(16).padStart(2, '0')).join('');
}

const CRC_TABLE = Array.from({ length: 256 }, (_, i) => {
  let c = i << 24;
  for (let k = 0; k < 8; k++) c = c & 0x80000000 ? (c << 1) ^ 0x04C11DB7 : c << 1;
  return c >>> 0;
});
function crc32mpeg2(data) {
  let crc = 0xFFFFFFFF;
  for (const b of data) crc = ((crc << 8) ^ CRC_TABLE[((crc >>> 24) ^ b) & 0xFF]) >>> 0;
  return crc;
}

const nib = (v, n) => Array.from({ length: n }, (_, i) => Math.floor(v / 16 ** (n - 1 - i)) & 0xF);
const unnib = a => a.reduce((v, b) => v * 16 + b, 0);

// 32 bytes <-> 37 seven-bit bytes (the 256 bits, then 3 zero bits).
function pack(block) {
  const out = [];
  let acc = 0, n = 0;
  for (const b of [...block, 0]) {
    acc = (acc << 8) | b; n += 8;
    while (n >= 7 && out.length < 37) { n -= 7; out.push((acc >> n) & 0x7F); }
    acc &= (1 << n) - 1;
  }
  return out;
}
function unpack(p) {
  if (p.length !== 37) throw Error('bad block');
  const out = [];
  let acc = 0, n = 0;
  for (const b of p) {
    acc = (acc << 7) | b; n += 7;
    while (n >= 8 && out.length < 32) { n -= 8; out.push((acc >> n) & 0xFF); }
    acc &= (1 << n) - 1;
  }
  return out;
}

export function split(u8) {
  const msgs = [];
  for (let i = 0; i < u8.length;) {
    const s = u8.indexOf(0xF0, i), e = u8.indexOf(0xF7, s);
    if (s < 0 || e < 0) break;
    msgs.push(u8.slice(s, e + 1)); i = e + 1;
  }
  const cmds = msgs.map(m => m[5]);
  if (cmds[0] !== 0x71 || cmds[1] !== 0x7C || cmds.at(-1) !== 0x73 || cmds.slice(2, -1).some(c => c !== 0x72)) throw Error('unexpected message order');
  return msgs;
}

function decode(syx) {
  const msgs = split(syx).map(m => m.slice(6, -1));
  const hdr = [...msgs[1]];
  const size = unnib(hdr.slice(7, 15)), crc = unnib(hdr.slice(15, 23));
  const image = new Uint8Array(msgs.length * 32);
  image.set(unpack(msgs.at(-1)), 0);
  msgs.slice(2, -1).forEach((p, k) => image.set(unpack(p), (k + 1) * 32));
  const out = image.slice(0, size);
  if (crc32mpeg2(out) !== crc) throw Error('CRC mismatch');
  return out;
}

function encode(image) {                     // image: a whole number of 32-byte blocks
  const out = [];
  const msg = (cmd, body) => out.push(...HDR, cmd, ...body, 0xF7);
  msg(0x71, [0x01, PRODUCT, 0x00, 0x00, ...nib(PROTO, 4)]);
  msg(0x7C, [0x00, ...nib(PROTO, 6), ...nib(image.length, 8), ...nib(crc32mpeg2(image), 8)]);
  for (let i = 32; i < image.length; i += 32) msg(0x72, pack(image.subarray(i, i + 32)));
  msg(0x73, pack(image.subarray(0, 32)));
  return new Uint8Array(out);
}

// The official 1.2.1 .syx (checked) -> LOOP06 .syx (checked against the Python build).
export async function buildLoop(stockSyx) {
  if ((await sha256(stockSyx)) !== PATCH.stockSyx) throw Error('not Novation’s 1.2.1 file');
  const stock = decode(new Uint8Array(stockSyx));
  if ((await sha256(stock)) !== PATCH.stockImage) throw Error('unexpected image');
  const image = new Uint8Array(PATCH.size).fill(0xFF);
  image.set(stock.subarray(0, Math.min(stock.length, PATCH.size)));
  for (const [off, hex] of PATCH.edits)
    image.set(hex.match(/../g).map(h => parseInt(h, 16)), off);
  const syx = encode(image);
  if ((await sha256(syx)) !== PATCH.sha) throw Error('patch check failed: not sending it');
  return syx;
}

export const STOCK_SHA = PATCH.stockSyx;
export const LOOP_SHA = PATCH.sha;
